const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_TERM = 3;
const PEERS = ['n1', 'n2'];
// role: 'follower' | 'candidate' | 'leader' | 'shutdown'
// votedFor: 'nobody' | 'itself' | 'n1' | 'n2' — the vote in the current term
const INITIAL_STATE = { role: 'follower', term: 0, votedFor: 'nobody' };

const isTerm = (t) => typeof t === 'number' && Number.isInteger(t) && t >= 1 && t <= MAX_TERM;

const VOTE_DOMAIN = [];
for (const candidate of ['n1', 'n2', 'n3', 'itself', 'nobody']) {
  for (const term of [0, 1, 2, 3, 4, 1.5]) VOTE_DOMAIN.push({ candidate, term });
}

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      role: { type: 'string' },
      term: { type: 'number' },
      votedFor: { type: 'string' },
    },
    actions: {
      electionTimeout: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      electionWon: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      newerTermSeen: {
        action: (data = {}) => ({ ...data }),
        schema: { term: { type: 'number' } },
        domain: [-1, 0, 1, 2, 3, 4, 1.5].map((term) => ({ term })),
      },
      quorumLost: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      shutdown: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      voteRequested: {
        action: (data = {}) => ({ ...data }),
        schema: { candidate: { type: 'string' }, term: { type: 'number' } },
        domain: VOTE_DOMAIN,
      },
    },
    acceptors: {
      electionTimeout: (model) => (proposal, { reject, next }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role === 'leader') return reject('the leader does not time out');
        if (model.term >= MAX_TERM) return reject('no term after 3');
        next.role = 'candidate';
        next.term = model.term + 1;
        next.votedFor = 'itself';
      },
      electionWon: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'candidate') return reject('only a candidate can win an election');
        next.role = 'leader';
        unchanged('term', 'votedFor');
      },
      newerTermSeen: (model) => (proposal, { reject, next }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (!isTerm(proposal.term)) return reject('term must be an integer from 1 to 3');
        if (proposal.term <= model.term) return reject('term is not newer');
        next.role = 'follower';
        next.term = proposal.term;
        next.votedFor = 'nobody';
      },
      quorumLost: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'leader') return reject('only the leader can lose its quorum');
        next.role = 'follower';
        unchanged('term', 'votedFor');
      },
      shutdown: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        next.role = 'shutdown';
        unchanged('term', 'votedFor');
      },
      voteRequested: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        const { candidate, term } = proposal;
        if (!PEERS.includes(candidate)) return reject('candidate must be n1 or n2');
        if (!isTerm(term)) return reject('term must be an integer from 1 to 3');
        if (term > model.term) {
          next.role = 'follower';
          next.term = term;
          next.votedFor = candidate;
          return;
        }
        if (term < model.term) return reject('vote requested for an older term');
        if (model.role !== 'follower') return reject('only a follower grants a vote in its own term');
        if (model.votedFor === candidate) {
          // granted again: same vote, nothing changes
          unchanged('role', 'term', 'votedFor');
          return;
        }
        if (model.votedFor !== 'nobody') return reject('already voted in this term');
        next.votedFor = candidate;
        unchanged('role', 'term');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  electionTimeout: (data = {}) => intents.electionTimeout(data),
  electionWon: (data = {}) => intents.electionWon(data),
  newerTermSeen: (data = {}) => intents.newerTermSeen(data),
  quorumLost: (data = {}) => intents.quorumLost(data),
  shutdown: (data = {}) => intents.shutdown(data),
  voteRequested: (data = {}) => intents.voteRequested(data),
};

module.exports = { instance, init, actions, getState, setState };

