import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('starts a follower in term 0 that has not voted', async () => {
  const h = await createHost();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
});

test('election, win, quorum lost', async () => {
  const h = await createHost();
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 1, votedFor: 'itself' });
  assert.equal((await h.electionTimeout()).ok, true);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 2, votedFor: 'itself' });
  assert.equal((await h.electionWon()).ok, true);
  assert.deepEqual(await h.node(), { role: 'leader', term: 2, votedFor: 'itself' });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, true);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'itself' });
  assert.equal((await h.quorumLost()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
});

test('term 3 cap', async () => {
  const h = await createHost();
  for (let i = 0; i < 3; i++) assert.equal((await h.electionTimeout()).ok, true);
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 3, votedFor: 'itself' });
});

test('newer term seen', async () => {
  const h = await createHost();
  for (const bad of [0, 4, -1, 1.5, NaN]) assert.equal((await h.newerTermSeen(bad)).ok, false);
  await h.electionTimeout();
  await h.electionWon();
  assert.equal((await h.newerTermSeen(1)).ok, false);
  assert.equal((await h.newerTermSeen(3)).ok, true);
  assert.deepEqual(await h.node(), { role: 'follower', term: 3, votedFor: 'nobody' });
});

test('shutdown is final', async () => {
  const h = await createHost();
  await h.electionTimeout();
  assert.equal((await h.shutdown()).ok, true);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1, votedFor: 'itself' });
  for (const r of [await h.shutdown(), await h.electionTimeout(), await h.electionWon(),
    await h.newerTermSeen(3), await h.quorumLost(), await h.voteRequested('n1', 3)]) assert.equal(r.ok, false);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1, votedFor: 'itself' });
});

test('vote request validation', async () => {
  const h = await createHost();
  for (const [c, t] of [['n3', 1], ['itself', 1], ['nobody', 1], ['n1', 0], ['n1', 4], ['n1', 1.5]] as const) {
    assert.equal((await h.voteRequested(c, t)).ok, false);
  }
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
});

test('vote in a newer term: becomes follower and grants', async () => {
  const h = await createHost();
  await h.electionTimeout();
  await h.electionWon();
  assert.deepEqual(await h.voteRequested('n2', 2), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'n2' });
});

test('at most one vote per term', async () => {
  const h = await createHost();
  await h.newerTermSeen(1);
  assert.equal((await h.voteRequested('n1', 1)).ok, true);
  assert.equal((await h.voteRequested('n1', 1)).ok, true);
  assert.equal((await h.voteRequested('n2', 1)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'n1' });
  assert.equal((await h.voteRequested('n2', 0 + 1)).ok, false);
  // older term refused
  await h.newerTermSeen(2);
  assert.equal((await h.voteRequested('n2', 1)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'nobody' });
});

test('election lost: follower in the same term, keeps its vote for itself', async () => {
  const h = await createHost();
  assert.equal((await h.electionLost()).ok, false);
  await h.electionTimeout();
  assert.deepEqual(await h.electionLost(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'itself' });
  assert.equal((await h.electionLost()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.voteRequested('n1', 1)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'itself' });
  assert.equal((await h.voteRequested('n1', 2)).ok, true);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'n1' });
  await h.electionTimeout();
  await h.electionWon();
  assert.equal((await h.electionLost()).ok, false);
  await h.shutdown();
  assert.equal((await h.electionLost()).ok, false);
});

test('candidate and leader do not grant in their own term', async () => {
  const h = await createHost();
  await h.electionTimeout();
  assert.equal((await h.voteRequested('n1', 1)).ok, false);
  await h.electionWon();
  assert.equal((await h.voteRequested('n1', 1)).ok, false);
  await h.quorumLost();
  assert.equal((await h.voteRequested('n1', 1)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'itself' });
});

