        next.term = proposal.term;
        next.votedFor = 'nobody';
      },
      quorumLost: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'leader') return reject('only the leader can lose its quorum');
        next.role = 'follower';
        unchanged('term', 'votedFor');
      },
      shutdown: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        next.role = 'shutdown';
        unchanged('term', 'votedFor');
      },
      voteRequested: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        const { candidate, term } = proposal;
        if (!PEERS.includes(candidate)) return reject('candidate must be n1 or n2');
        if (!isTerm(term)) return reject('term must be an integer from 1 to 3');
        if (term > model.term) {
          next.role = 'follower';
          next.term = term;
          next.votedFor = candidate;
          return;
        }
        if (term < model.term) return reject('vote requested for an older term');
        if (model.role !== 'follower') return reject('only a follower grants a vote in its own term');
        if (model.votedFor === candidate) {
          // granted again: same vote, nothing changes
          unchanged('role', 'term', 'votedFor');
          return;
        }
        if (model.votedFor !== 'nobody') return reject('already voted in this term');
        next.votedFor = candidate;
        unchanged('role', 'term');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  electionTimeout: (data = {}) => intents.electionTimeout(data),
  electionWon: (data = {}) => intents.electionWon(data),
  electionLost: (data = {}) => intents.electionLost(data),
  newerTermSeen: (data = {}) => intents.newerTermSeen(data),
  quorumLost: (data = {}) => intents.quorumLost(data),
  shutdown: (data = {}) => intents.shutdown(data),
  voteRequested: (data = {}) => intents.voteRequested(data),
};

module.exports = { instance, init, actions, getState, setState };

